# rna GPT-2 small -- batch 1024, lr 0.000759
# The rna batch-size grid of the 2026-11-20 directive. Generated by
# scripts/rna_batch_sweep_configs.py from the derived arm inventory; edit the
# inventory and regenerate rather than editing this file.
#
# GPT-2 runs one rate per batch (§3), so this arm is the batch.
#
# The budget is fixed in blocks, not in steps (§2): 309,657,600 packed blocks of
# 1,024 tokens = 317,089,382,400 tokens, the same for all 68 arms and the same as the
# existing grid's 120,960 x 2,560. At batch 1024 that is 302,400 steps, so the
# five batches cover the same data and their curves meet at the same block.
#
# The rate is this size's adopted 2,560 rate scaled by sqrt(batch / 2560) (§3):
# 1 x sqrt(1024/2560) x 0.0012 = 0.000759.
#
# Warmup is 2 % of this arm's own length (§2), truncated: 6,048 of
# 302,400.
#
# One GPU takes 32 blocks and the accumulation count carries the rest (§4):
# 32 x 32 = 1024. Held across the five batches of this size, so what differs between
# them is the accumulation count and nothing else.
#
# The adopted arm fixes its validation rows (deterministic_val_eval), and §6 leaves GPT-2's evaluation alone, so that carries through the import.

# Everything else comes from gpt2_small_lr1p2e3_9ep.py, imported rather than copied, so the
# corpus, the tokenizer, the split, the mask rate, the sequence length, the
# document masking and the seed are the adopted arm's own (§8).

from molcrawl.tasks.pretrain.configs.rna.gpt2_small_lr1p2e3_9ep import *  # noqa: F401,F403

max_iters = 302400
lr_decay_iters = 302400  # the decay length is this arm's own run (§8)
warmup_iters = 6048  # 2 % of max_iters (§2)
learning_rate = 0.000759
min_lr = 7.59e-05  # a tenth of this arm's own peak (§8)
# Pretraining runs the whole schedule (§8). train.py's own default is True with a
# patience of 10, so leaving this out would stop an arm part-way.
early_stopping = False

# 225 evaluation points, at the same block positions as every other batch
# in the grid (§2).
eval_interval = 1344
# nanoGPT writes ckpt.pt whenever the validation loss improves, which is what keeps
# the reported minimum's weights (§4 of the extension directive); there is no save
# interval to set.

# 32 x 32 = 1024 (§4). nanoGPT divides the accumulation count across the four ranks, so the
# global batch is micro x accumulation with no GPU factor.
batch_size = 32
gradient_accumulation_steps = 32
# Declared so train.py stops a launch whose shape would build another batch (§5).
expected_global_batch = 1024

import os as _os  # noqa: E402

_runs_root = _os.environ.get("MODEL_OUTPUT_ROOT")
if not _runs_root:
    raise SystemExit(
        "set MODEL_OUTPUT_ROOT to a runs root outside any input tree; "
        "deriving it from LEARNING_SOURCE_DIR puts checkpoints beside the corpus"
    )
out_dir = _os.path.join(_runs_root, "rna-gpt2-small-b1024-lr7p59e4")
tensorboard_dir = out_dir
